//! The Slint app: a hidden window, the worker thread and the event-loop wiring.
//!
//! Threading (Task 201): the Slint event loop owns the main thread. `App` (storage, capture) is
//! created and used only on the worker thread; results return with
//! `Weak::upgrade_in_event_loop` (`slint::invoke_from_event_loop`). IPC commands arrive on the
//! IPC thread and are handed to the event loop the same way. Nothing here blocks the UI thread
//! on storage, capture or IPC. Logging is content-free (GC-06).

/// Code generated by `slint-build` from `ui/*.slint`; it is not ours to edit, so the workspace
/// lints (`unwrap_used` and friends) are relaxed for this module only.
#[allow(
    clippy::all,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    unsafe_code,
    dead_code
)]
mod generated {
    slint::include_modules!();
}
pub use generated::{MainWindow, Strings, Theme};

use crate::log::{Log, Val};
use crate::single_instance::Command;
use crate::theme;
use darkclip_app::api::CaptureStatus;
use darkclip_app::settings::LoadOutcome;
use darkclip_app::{App, AppEvent, CaptureConfig};
use darkclip_core::i18n::{t, Lang, Msg};
use slint::{ComponentHandle, Weak};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{self, Sender};
use std::sync::Arc;
use std::thread::JoinHandle;

/// What the event loop does for a command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Show,
    Hide,
    Quit,
}

/// Pure: `Toggle` flips the window, `ShowSettings` shows it (the settings window arrives in a
/// later task), `Quit` ends the loop.
pub fn action_for(window_visible: bool, cmd: Command) -> Action {
    match cmd {
        Command::Toggle if window_visible => Action::Hide,
        Command::Toggle | Command::ShowSettings => Action::Show,
        Command::Quit => Action::Quit,
    }
}

/// Which message describes the capture state.
pub fn status_msg(s: CaptureStatus) -> Msg {
    match s {
        CaptureStatus::Active => Msg::UiCaptureActive,
        CaptureStatus::Paused => Msg::UiCapturePaused,
        CaptureStatus::Private => Msg::UiCapturePrivate,
        CaptureStatus::Unavailable(_) => Msg::UiCaptureUnavailable,
    }
}

/// Language rule (requirement 6): the saved setting wins; on a first run the OS UI language
/// decides (Vietnamese if the OS is Vietnamese, otherwise English).
pub fn effective_lang(first_run: bool, os: Lang, saved: Lang) -> Lang {
    if first_run {
        os
    } else {
        saved
    }
}

/// Primary language id 0x2A is Vietnamese.
pub fn lang_from_langid(id: u16) -> Lang {
    if id & 0x03ff == 0x2a {
        Lang::Vi
    } else {
        Lang::En
    }
}

/// The OS UI language (English when it cannot be told).
pub fn os_lang() -> Lang {
    #[cfg(windows)]
    {
        lang_from_langid(crate::single_instance::ui_language_id())
    }
    #[cfg(not(windows))]
    {
        Lang::En
    }
}

fn set_strings(w: &MainWindow, lang: Lang, status: Option<CaptureStatus>) {
    let s = w.global::<Strings>();
    s.set_app_name(t(lang, Msg::UiAppName).into());
    s.set_placeholder(t(lang, Msg::UiPopupPlaceholder).into());
    let status = status.map_or(Msg::UiStarting, status_msg);
    s.set_status(t(lang, status).into());
}

type Job = Box<dyn FnOnce(&App) + Send>;

enum WorkerMsg {
    /// Re-read status and language, then update the window.
    Refresh,
    /// Run an `App` call on the worker (storage never runs on the UI thread).
    Run(Job),
    Stop,
}

/// The thread that owns `App`.
pub struct Worker {
    tx: Sender<WorkerMsg>,
    handle: Option<JoinHandle<()>>,
    failed: Arc<AtomicBool>,
}

pub struct StartArgs {
    pub data_dir: PathBuf,
    pub settings_path: PathBuf,
    pub os_lang: Lang,
}

/// Asks the event loop to end (callable from any thread).
fn quit_soon() {
    let _ = slint::invoke_from_event_loop(|| {
        let _ = slint::quit_event_loop();
    });
}

/// Reads status and language on the worker, then updates the window on the event loop.
fn push_status(app: &App, ui: &Weak<MainWindow>) {
    let (status, lang) = (app.status().capture, app.lang());
    let _ = ui.upgrade_in_event_loop(move |w| set_strings(&w, lang, Some(status)));
}

impl Worker {
    pub fn spawn(args: StartArgs, ui: Weak<MainWindow>, log: Arc<Log>) -> Option<Worker> {
        let (tx, rx) = mpsc::channel::<WorkerMsg>();
        let failed = Arc::new(AtomicBool::new(false));
        let worker_failed = Arc::clone(&failed);
        let refresh_tx = tx.clone();
        let handle = std::thread::Builder::new()
            .name("darkclip-worker".into())
            .spawn(move || {
                let Ok(bundle) = crate::platform() else {
                    log.event("start_failed", &[("stage", Val::Name("platform"))]);
                    worker_failed.store(true, Ordering::SeqCst);
                    return quit_soon();
                };
                let (ev_tx, ev_rx) = mpsc::channel::<AppEvent>();
                let started = App::start(
                    bundle,
                    &args.data_dir,
                    &args.settings_path,
                    Arc::new(crate::SystemClock),
                    CaptureConfig::default(),
                    ev_tx,
                );
                let (app, outcome) = match started {
                    Ok(v) => v,
                    Err(e) => {
                        log.event("start_failed", &[("code", Val::Name(e.code()))]);
                        worker_failed.store(true, Ordering::SeqCst);
                        return quit_soon();
                    }
                };
                crate::log_capabilities(&log, &app.capabilities());
                // First run: follow the OS language once and remember it.
                let saved = app.lang();
                let lang = effective_lang(
                    matches!(outcome, LoadOutcome::Defaulted),
                    args.os_lang,
                    saved,
                );
                if lang != saved {
                    let mut s = app.settings();
                    s.ui.language = lang;
                    let _ = app.update_settings(s);
                }
                // Every AppEvent triggers a refresh; the forwarder ends when the pump ends.
                let fwd = std::thread::Builder::new()
                    .name("darkclip-ui-events".into())
                    .spawn(move || {
                        for _ in ev_rx {
                            if refresh_tx.send(WorkerMsg::Refresh).is_err() {
                                break;
                            }
                        }
                    });
                log.event("running", &[]);
                push_status(&app, &ui);
                for m in rx {
                    match m {
                        WorkerMsg::Refresh => push_status(&app, &ui),
                        WorkerMsg::Run(job) => job(&app),
                        WorkerMsg::Stop => break,
                    }
                }
                match app.shutdown() {
                    Ok(()) => log.event("stop", &[]),
                    Err(e) => log.event("stop_failed", &[("code", Val::Name(e.code()))]),
                }
                if let Ok(f) = fwd {
                    let _ = f.join();
                }
            })
            .ok()?;
        Some(Worker {
            tx,
            handle: Some(handle),
            failed,
        })
    }

    /// Queues an `App` call on the worker thread.
    #[allow(dead_code)] // first user arrives with the popup content (Task 204)
    pub fn post(&self, job: impl FnOnce(&App) + Send + 'static) {
        let _ = self.tx.send(WorkerMsg::Run(Box::new(job)));
    }

    /// True when the worker could not start the app.
    pub fn failed(&self) -> bool {
        self.failed.load(Ordering::SeqCst)
    }

    /// Stops the app (bounded by `App::shutdown`'s 2 s) and joins the thread.
    pub fn stop(mut self) {
        let _ = self.tx.send(WorkerMsg::Stop);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

/// Applies a command to the window; runs on the event loop thread.
fn apply_command(w: &MainWindow, cmd: Command) {
    match action_for(w.window().is_visible(), cmd) {
        Action::Show => {
            let _ = w.show();
        }
        Action::Hide => {
            let _ = w.hide();
        }
        Action::Quit => {
            let _ = slint::quit_event_loop();
        }
    }
}

/// Everything `run` needs; built by `main`.
pub struct RunArgs {
    pub start: StartArgs,
    pub exit_after_ms: Option<u64>,
    pub log: Arc<Log>,
}

/// Callback the IPC server calls for each valid command (on its own thread).
pub type CommandHandler = Box<dyn Fn(Command) + Send + Sync>;

/// Creates the hidden window and runs the event loop until quit. `listen` installs the IPC
/// server with the handler it must call for each valid command. Returns false when the app
/// could not start.
pub fn run(args: RunArgs, listen: impl FnOnce(CommandHandler) -> Result<(), ()>) -> bool {
    let log = args.log;
    let Ok(window) = MainWindow::new() else {
        log.event("start_failed", &[("stage", Val::Name("window"))]);
        return false;
    };
    theme::apply(&window);
    set_strings(&window, args.start.os_lang, None);
    // Closing the window only hides it; the app keeps running (tray arrives in Task 202).

    let weak = window.as_weak();
    let ipc_log = Arc::clone(&log);
    let handler: CommandHandler = Box::new(move |cmd| {
        ipc_log.event("ipc_command", &[("cmd", Val::Name(cmd.name()))]);
        let _ = weak.upgrade_in_event_loop(move |w| apply_command(&w, cmd));
    });
    if listen(handler).is_err() {
        log.event("start_failed", &[("stage", Val::Name("ipc"))]);
        return false;
    }

    let Some(worker) = Worker::spawn(args.start, window.as_weak(), Arc::clone(&log)) else {
        log.event("start_failed", &[("stage", Val::Name("worker"))]);
        return false;
    };

    if let Some(ms) = args.exit_after_ms {
        let _ = std::thread::Builder::new()
            .name("darkclip-exit-timer".into())
            .spawn(move || {
                std::thread::sleep(std::time::Duration::from_millis(ms));
                quit_soon();
            });
    }
    let _ = ctrlc::set_handler(quit_soon);

    let looped = slint::run_event_loop_until_quit();
    let failed = worker.failed();
    log.event("stop_requested", &[]);
    worker.stop();
    looped.is_ok() && !failed
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn toggle_flips_visibility() {
        assert_eq!(action_for(false, Command::Toggle), Action::Show);
        assert_eq!(action_for(true, Command::Toggle), Action::Hide);
    }

    #[test]
    fn show_settings_always_shows_and_quit_quits() {
        assert_eq!(action_for(false, Command::ShowSettings), Action::Show);
        assert_eq!(action_for(true, Command::ShowSettings), Action::Show);
        assert_eq!(action_for(true, Command::Quit), Action::Quit);
        assert_eq!(action_for(false, Command::Quit), Action::Quit);
    }

    #[test]
    fn every_capture_status_has_its_own_message() {
        assert_eq!(status_msg(CaptureStatus::Active), Msg::UiCaptureActive);
        assert_eq!(status_msg(CaptureStatus::Paused), Msg::UiCapturePaused);
        assert_eq!(status_msg(CaptureStatus::Private), Msg::UiCapturePrivate);
        assert_eq!(
            status_msg(CaptureStatus::Unavailable("x")),
            Msg::UiCaptureUnavailable
        );
    }

    #[test]
    fn vietnamese_os_language_is_detected() {
        assert_eq!(lang_from_langid(0x042a), Lang::Vi);
        assert_eq!(lang_from_langid(0x0409), Lang::En);
        assert_eq!(lang_from_langid(0x0407), Lang::En);
        assert_eq!(lang_from_langid(0), Lang::En);
    }

    #[test]
    fn saved_language_wins_except_on_first_run() {
        assert_eq!(effective_lang(true, Lang::Vi, Lang::En), Lang::Vi);
        assert_eq!(effective_lang(true, Lang::En, Lang::En), Lang::En);
        assert_eq!(effective_lang(false, Lang::Vi, Lang::En), Lang::En);
        assert_eq!(effective_lang(false, Lang::En, Lang::Vi), Lang::Vi);
    }
}
